with open('docs/method_notes.md', 'a', encoding='utf-8') as f:
    f.write('\n\n## Forgotten Asymmetry (1 October 2026)\n')
    f.write('Across 720 extracted accounts, 973 grounded remembered cues were identified against approximately 15 genuine memory gaps. Users overwhelmingly described knowing what they were looking for and being failed by retrieval, rather than failing to recall. The planned remembered/forgotten memory map was therefore restructured as a cue / breakdown / workaround chain.\n')
